import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, unzipInputArray } from '../test-utils'

describe('ApprovalRules with Datapills Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('ApprovalRules -> Fluent to XML', () => {
        test('ApprovalRules with user datapills in rules', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            // Verify action instances were created
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find the askForApproval action with user datapills
            const approvalActionWithUsers = actionInstances.find(
                (action: any) => action.comment === 'Ask for approval with user datapills'
            )
            expect(approvalActionWithUsers).toBeDefined()

            // Parse the action inputs
            const inputsArr = unzipInputArray(approvalActionWithUsers.values)
            const getInput = (name: string) => findInput(inputsArr, name)?.value

            // Verify basic approval fields
            expect(getInput('table')).toBe('incident')
            expect(getInput('approval_reason')).toBe('Test approval with datapills')
            expect(getInput('approval_field')).toBe('approval')
            expect(getInput('journal_field')).toBe('approval_history')

            // Verify approval_conditions contains datapills
            const approvalConditions = getInput('approval_conditions')
            expect(approvalConditions).toBeDefined()

            // Should contain datapill markers for users
            expect(approvalConditions).toEqual(
                'ApprovesAnyU[{{flow_variable.approverUser1}},{{flow_variable.approverUser2}},{{Created_1.current.sys_created_by}}]'
            )
            expect(approvalConditions).toContain('{{flow_variable.approverUser2}}')

            // Should contain trigger datapill
            expect(approvalConditions).toContain('{{Created_1.current.sys_created_by}}')

            // Should contain approval action keyword
            expect(approvalConditions).toMatch(/Approves/)
        })

        test('ApprovalRules with group datapills', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find the askForApproval action with group datapills
            const approvalActionWithGroups = actionInstances.find(
                (action: any) => action.comment === 'Ask for approval with group datapills'
            )
            expect(approvalActionWithGroups).toBeDefined()

            const inputsArr = unzipInputArray(approvalActionWithGroups.values)
            const approvalConditions = findInput(inputsArr, 'approval_conditions')?.value

            expect(approvalConditions).toBeDefined()

            // Should contain datapill markers for groups
            expect(approvalConditions).toContain('G[{{flow_variable.approverGroup}}]')

            // Should contain static user
            expect(approvalConditions).toContain('U[{{static.62826bf03710200044e0bfc8bcbe5df1}}]')

            // Should have All rule type
            expect(approvalConditions).toMatch(/All/)
        })

        test('ApprovalRules with percent rule using datapill', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find the askForApproval action with percent datapill
            const approvalActionWithPercent = actionInstances.find(
                (action: any) => action.comment === 'Ask for approval with percent datapill'
            )
            expect(approvalActionWithPercent).toBeDefined()

            const inputsArr = unzipInputArray(approvalActionWithPercent.values)
            const approvalConditions = findInput(inputsArr, 'approval_conditions')?.value

            expect(approvalConditions).toBeDefined()

            // Should contain percent with datapill
            // Format: 75%G[group_id] where 75 comes from flow variable
            expect(approvalConditions).toMatch(/{{flow_variable\.approvalPercentage}}%/)

            // Should contain group
            expect(approvalConditions).toContain('G[{{static.f6498860436012103cf32f0b76b8f2ce}}]')
        })

        test('ApprovalRules with complex datapills from multiple sources', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find the askForApproval action with complex datapills
            const approvalActionComplex = actionInstances.find(
                (action: any) => action.comment === 'Ask for approval with complex datapills from multiple sources'
            )
            expect(approvalActionComplex).toBeDefined()

            const inputsArr = unzipInputArray(approvalActionComplex.values)
            const approvalConditions = findInput(inputsArr, 'approval_conditions')?.value

            expect(approvalConditions).toBeDefined()

            // Should contain flow variable datapills
            expect(approvalConditions).toContain('{{flow_variable.approverUser1}}')
            expect(approvalConditions).toContain('{{flow_variable.approverUser2}}')
            expect(approvalConditions).toContain('{{flow_variable.approverGroup}}')

            // Should contain trigger datapills
            expect(approvalConditions).toContain('.current.sys_created_by}}')

            // Should have both Approves and Rejects actions
            expect(approvalConditions).toContain('Approves')
            expect(approvalConditions).toContain('Rejects')

            // Should have multiple rule types
            expect(approvalConditions).toMatch(/Any/)
            expect(approvalConditions).toMatch(/2#/) // for Count type rule # comes after count
        })

        test('ApprovalRules record field with datapill', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find actions with record datapill
            const approvalActionsWithRecordPill = actionInstances.filter((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                const record = findInput(inputsArr, 'record')?.value
                return record?.includes('{{')
            })

            expect(approvalActionsWithRecordPill.length).toBeGreaterThan(0)

            // Verify record field contains datapill
            const firstAction = approvalActionsWithRecordPill[0]
            const inputsArr = unzipInputArray(firstAction.values)
            const record = findInput(inputsArr, 'record')?.value

            // Record should contain action output or trigger datapill
            expect(record).toContain('{{')
            expect(record).toMatch(/(\.record}}|\.current}})/)
        })
    })

    describe('ApprovalRules Format and Structure', () => {
        test('ApprovalRules conditionType OR', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']
            const approvalAction = actionInstances[1] // Get first approval action

            const inputsArr = unzipInputArray(approvalAction.values)
            const approvalConditions = findInput(inputsArr, 'approval_conditions')?.value

            // Top-level condition should be OR (indicated by Or separator)
            expect(approvalConditions).toBeDefined()
            expect(approvalConditions).toContain(
                'ApprovesAnyU[{{flow_variable.approverUser1}},{{flow_variable.approverUser2}},{{Created_1.current.sys_created_by}}]'
            )
        })

        test('ApprovalRules rule separators', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']
            const complexApproval = actionInstances.find(
                (action: any) => action.comment === 'Ask for approval with complex datapills from multiple sources'
            )

            const inputsArr = unzipInputArray(complexApproval.values)
            const approvalConditions = findInput(inputsArr, 'approval_conditions')?.value

            // Should use proper separators
            // & for AND between rules in same group
            expect(approvalConditions).toContain('&')

            // Or for separator between Approves and Rejects
            expect(approvalConditions).toMatch(/Or/)
        })

        test('ApprovalRules rule type markers', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']
            const complexApproval = actionInstances.find(
                (action: any) => action.comment === 'Ask for approval with complex datapills from multiple sources'
            )

            const inputsArr = unzipInputArray(complexApproval.values)
            const approvalConditions = findInput(inputsArr, 'approval_conditions')?.value

            // Any rule: Any keyword
            expect(approvalConditions).toMatch(/Any/)

            // Count rule: number followed by #
            expect(approvalConditions).toMatch(/\d+#/)

            // Percent rule: number followed by %
            // (from another test, but structure should be consistent)
            const percentApproval = actionInstances.find(
                (action: any) => action.comment === 'Ask for approval with percent datapill'
            )
            if (percentApproval) {
                const percentInputs = unzipInputArray(percentApproval.values)
                const percentConditions = findInput(percentInputs, 'approval_conditions')?.value
                expect(percentConditions).toMatch(/\d+%|{{[^}]+}}%/)
            }
        })
    })

    describe('ApprovalRules with Datapills - Edge Cases', () => {
        test('ApprovalRules with empty groups', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find approval with users but empty groups
            const approvalWithUsers = actionInstances.find(
                (action: any) => action.comment === 'Ask for approval with user datapills'
            )

            const inputsArr = unzipInputArray(approvalWithUsers.values)
            const approvalConditions = findInput(inputsArr, 'approval_conditions')?.value

            // Should have users
            expect(approvalConditions).toContain('U[')

            // Empty groups should not break the format
            expect(approvalConditions).toBeDefined()
        })

        test('ApprovalRules with multiple RuleSets', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']
            const complexApproval = actionInstances.find(
                (action: any) => action.comment === 'Ask for approval with complex datapills from multiple sources'
            )

            const inputsArr = unzipInputArray(complexApproval.values)
            const approvalConditions = findInput(inputsArr, 'approval_conditions')?.value

            // Should have both Approves and Rejects
            expect(approvalConditions).toContain('Approves')
            expect(approvalConditions).toContain('Rejects')

            // Should be separated by Or
            expect(approvalConditions).toMatch(/Approves.*Or.*Rejects/s)
        })

        test('ApprovalRules datapill in different positions', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Collect all approval conditions
            const allConditions = actionInstances.map((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                return findInput(inputsArr, 'approval_conditions')?.value
            })

            // Datapills can appear in:
            // 1. User arrays: U[{{datapill}}]
            const hasUserDatapills = allConditions.some((cond) => cond && cond.includes('U[{{'))
            expect(hasUserDatapills).toBe(true)

            // 2. Group arrays: G[{{datapill}}]
            const hasGroupDatapills = allConditions.some((cond) => cond && cond.includes('G[{{'))
            expect(hasGroupDatapills).toBe(true)

            // 3. Percent values: {{datapill}}%
            const hasPercentDatapills = allConditions.some((cond) => cond && cond.match(/{{[^}]+}}%/))
            expect(hasPercentDatapills).toBe(true)
        })

        test('Multiple approval actions in single flow', async () => {
            const project = ctx.createProject({})
            const merged = await getMergedRecordUpdates(
                project,
                'approval-rules-datapills-example.now.ts',
                'core-actions/fluent/approval-rules'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Count askForApproval actions
            const approvalActions = actionInstances.filter((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                return findInput(inputsArr, 'approval_conditions') !== undefined
            })

            // Should have at least 4 approval actions
            expect(approvalActions.length).toBeGreaterThanOrEqual(4)

            // Each should have valid approval_conditions
            approvalActions.forEach((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                const conditions = findInput(inputsArr, 'approval_conditions')?.value
                expect(conditions).toBeDefined()
                expect(conditions.length).toBeGreaterThan(0)
            })
        })
    })
})
